#!/usr/bin/env node
// check-css-bundles.mjs — S256 (FE-5, audit remediation Phase 5): the per-page CSS
// bundle freshness + wiring gate.
//
// The four Projects-section pages link ONE generated bundle (public/css/board-bundle.css
// for board.html + sprint.html, public/css/projects-bundle.css for projects.html +
// project.html) instead of their 19-20 individual sheets. The bundles are COMMITTED
// files regenerated by every `build` — this gate makes a stale bundle a red CI line,
// not a silently-stale stylesheet served to the Projects section:
//
//   1. FRESHNESS: the committed bundle bytes must equal the deterministic
//      regeneration (header + parts joined, the exact recipe scripts/build.mjs runs).
//   2. ORDER CONTRACT: board-bundle's LAST part is rtl.css (the desktop island
//      contract — the island's CSS link order collapses into this one file).
//   3. HTML WIRING (canonical tree only — skipped when wired, the check-dist-wiring
//      doctrine): each bundle page links its bundle exactly once, links NONE of the
//      parts individually, and every part keeps ≥1 carrier page OUTSIDE the bundle
//      set (the SW synthesizes bundles from the precached sheets — a sheet that no
//      non-bundle page links anymore would silently leave the precache union).
//   4. ?v= CONSISTENCY: one version per bundle across its pages (check-cache-bust's
//      modified-files rule, pre-applied — the bundles are generated artifacts whose
//      ?v= discipline is "bump when the content moves").
//
// Run: node scripts/check-css-bundles.mjs   (after any build; also standalone)
// CI: wired into .github/workflows/ci.yml after the cache-bust check.

import { readFileSync, existsSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

const ROOT = process.cwd()
const CSS_DIR = join(ROOT, 'public', 'css')
const PUBLIC_DIR = join(ROOT, 'public')

// The bundle definitions — MUST mirror scripts/build.mjs's CSS_BUNDLES exactly
// (name, pages, ordered parts). A divergence here fails loudly on the next build
// (the committed bytes stop matching this regeneration) — re-record both together.
const CSS_BUNDLES = [
  {
    name: 'board-bundle.css',
    pages: ['board.html', 'sprint.html'],
    parts: [
      'variables.css', 'base.css', 'layout.css', 'dashboard.css', 'dashboard-todo.css',
      'components.css', 'canvas.css', 'quicknotes.css', 'to-do-list.css', 'polish-ui.css',
      'calendar.css', 'notifications.css', 'polish-batch.css', 'project-header.css',
      'devboard.css', 'misc.css', 'themes.css', 'claude-dark-theme.css', 'rtl.css',
    ],
  },
  {
    name: 'projects-bundle.css',
    pages: ['projects.html', 'project.html'],
    parts: [
      'variables.css', 'base.css', 'layout.css', 'dashboard.css', 'dashboard-todo.css',
      'components.css', 'canvas.css', 'quicknotes.css', 'to-do-list.css', 'polish-ui.css',
      'calendar.css', 'notifications.css', 'polish-batch.css', 'project-header.css',
      'devboard.css', 'misc.css', 'themes.css', 'claude-dark-theme.css', 'rtl.css', 'magic-wand.css',
    ],
  },
]

// build.mjs's generator recipe, duplicated deliberately (the drift detector must not
// share the generator's code object — it pins the OUTPUT format).
function regenerate(bundle) {
  const header = [
    '/* ' + bundle.name + ' — GENERATED by scripts/build.mjs (S256, FE-5 — the audit\'s CSS/asset diet). DO NOT EDIT BY HAND.',
    ' * The concatenated <link> set of ' + bundle.pages.join(' + ') + ', in the EXACT current order',
    ' * (cascade order preserved; rtl.css is the LAST part of board-bundle — the desktop island contract).',
    ' * Regenerate with any build (`npm run build` / `bun run build`); scripts/check-css-bundles.mjs guards the freshness.',
    ' * Parts (order matters): ' + bundle.parts.join(', ') + ' */',
    '',
  ].join('\n')
  const body = bundle.parts.map((p) => readFileSync(join(CSS_DIR, p), 'utf8')).join('\n')
  return header + body + '\n'
}

const problems = []
const bundlePages = new Set(CSS_BUNDLES.flatMap((b) => b.pages))

for (const bundle of CSS_BUNDLES) {
  const path = join(CSS_DIR, bundle.name)
  if (!existsSync(path)) {
    problems.push(`public/css/${bundle.name} is MISSING — run \`npm run build\` (scripts/build.mjs generates it).`)
    continue
  }
  // 1. freshness — byte-identical regeneration
  const committed = readFileSync(path, 'utf8')
  const want = regenerate(bundle)
  if (committed !== want) {
    problems.push(`public/css/${bundle.name} is STALE — its bytes differ from the regeneration from the ${bundle.parts.length} sheets (a sheet changed without a rebuild, or the generator recipe changed). Re-run \`npm run build\` and commit the regenerated bundle + its ?v= bump.`)
  }
  // 2. the rtl-last desktop contract (board-bundle only — projects' own page order
  //    carries magic-wand after rtl, preserved verbatim by design)
  if (bundle.name === 'board-bundle.css' && bundle.parts[bundle.parts.length - 1] !== 'rtl.css') {
    problems.push('board-bundle.css: rtl.css must be the LAST part (the desktop island contract).')
  }
}

// 3+4. HTML wiring + ?v= consistency — canonical tree only
const htmls = CSS_BUNDLES.flatMap((b) => b.pages).map((p) => [p, readFileSync(join(PUBLIC_DIR, p), 'utf8')])
const wired = htmls.some(([, html]) => /\/dist\/[A-Za-z0-9_-]+\.[0-9a-f]{8}\.(?:js|css)/.test(html))
if (wired) {
  console.log('(wired tree — the HTML wiring assertions skipped; check-dist-wiring owns that form)')
} else {
  for (const bundle of CSS_BUNDLES) {
    const versions = new Set()
    for (const page of bundle.pages) {
      const html = readFileSync(join(PUBLIC_DIR, page), 'utf8')
      const bundleRefs = [...html.matchAll(new RegExp(`href="/css/${bundle.name}\\?v=(\\d+)"`, 'g'))]
      if (bundleRefs.length !== 1) {
        problems.push(`${page}: expected exactly ONE <link> for /css/${bundle.name}?v=N — found ${bundleRefs.length}.`)
      }
      for (const m of bundleRefs) versions.add(m[1])
      // the page must not link any of the bundle's parts individually (the head swap
      // is total — a leftover sheet link would double-load CSS on that page)
      for (const part of bundle.parts) {
        if (new RegExp(`href="/css/${part.replace(/\./g, '\\.')}\\?v=\\d+"`).test(html)) {
          problems.push(`${page}: still links the individual sheet ${part} — the head swap to ${bundle.name} must be total.`)
        }
      }
    }
    if (versions.size > 1) {
      problems.push(`${bundle.name}: inconsistent ?v= across its pages (${[...versions].join(', ')}).`)
    }
  }
  // every part keeps a carrier OUTSIDE the bundle pages (the SW synthesis reads the
  // precached sheets; the sheets' own ?v= links on other pages are what keeps them in
  // the manifest + install payload)
  const allHtml = readdirSync(PUBLIC_DIR).filter((f) => f.endsWith('.html') && !bundlePages.has(f))
  for (const part of new Set(CSS_BUNDLES.flatMap((b) => b.parts))) {
    const carried = allHtml.some((f) => {
      const html = readFileSync(join(PUBLIC_DIR, f), 'utf8')
      return new RegExp(`href="/css/${part.replace(/\./g, '\\.')}\\?v=\\d+"`).test(html)
    })
    if (!carried) {
      problems.push(`${part}: no page outside the bundle set links it anymore — the SW's bundle synthesis (and the precache union) would lose it. Keep at least one individual-sheet carrier or revisit the bundle design.`)
    }
  }
}

if (problems.length > 0) {
  console.error('FAIL: the per-page CSS bundle check found issues:')
  for (const p of problems) console.error(`  ✗ ${p}`)
  process.exit(1)
}
console.log(`PASS: ${CSS_BUNDLES.length} per-page CSS bundle(s) fresh + wired (board-bundle rtl-last contract holds)`)
